{"implementation": "def solve(case):
    # Validate required fields
    if 'edges' not in case or 'refinement' not in case:
        raise ValueError("Missing required fields")
    edges = case['edges']
    refinement = case['refinement']
    if not isinstance(edges, list) or not isinstance(refinement, dict):
        raise ValueError("Invalid types")
    # Build members dict
    members = {}
    for node, comm in refinement.items():
        members.setdefault(comm, []).append(node)
    # Sort each community list
    for comm in members:
        members[comm].sort()
    # Build aggregate edges dict
    aggregate = {}
    for u, v, w in edges:
        if not (isinstance(u, str) and isinstance(v, str) and isinstance(w, (int, float))):
            raise ValueError("Invalid edge format")
        cu = refinement.get(u)
        cv = refinement.get(v)
        if cu is None or cv is None:
            raise ValueError("Node not in refinement")
        # Canonicalize undirected
        if cu <= cv:
            key = (cu, cv)
        else:
            key = (cv, cu)
        aggregate[key] = aggregate.get(key, 0) + w
    # Convert to list of lists and sort
    aggregate_edges = [[k[0], k[1], v] for k, v in aggregate.items()]
    aggregate_edges.sort(key=lambda x: (x[0], x[1]))
    return {"aggregate_edges": aggregate_edges, "members": members}
